"""Exp-substitution x |-> e^x as a tower-height shift: expShift_var, shift_lt_iff, injectivity."""
from __future__ import annotations
from typing import Dict, List, Tuple

TransMono = Dict[int, float]

def mono(h: int, a: float) -> TransMono:
    return {} if a == 0.0 else {h: a}

def shift(m: TransMono) -> TransMono:
    """shift_mono: raise every tower height by one."""
    return {h + 1: a for h, a in m.items()}

def compare_mono(m1: TransMono, m2: TransMono) -> int:
    for h in sorted(set(m1) | set(m2), reverse=True):
        a1, a2 = m1.get(h, 0.0), m2.get(h, 0.0)
        if a1 != a2:
            return -1 if a1 < a2 else 1
    return 0

if __name__ == "__main__":
    assert shift(mono(0, 1.0)) == mono(1, 1.0)   # expShift_var:  x -> exp x
    assert shift(mono(1, 1.0)) == mono(2, 1.0)   # expShift_exp:  exp x -> exp(exp x)
    assert shift(mono(-1, 1.0)) == mono(0, 1.0)  # expShift_log:  log x -> x
    print("expShift_var / expShift_exp / expShift_log confirmed")
    # shift_lt_iff: the shift preserves the dominance order on every pair.
    samples: List[TransMono] = [mono(h, e) for h in range(-3, 4) for e in (-2.0, 1.0, 5.0)]
    assert all(compare_mono(shift(p), shift(q)) == compare_mono(p, q)
               for p in samples for q in samples)
    print(f"shift_lt_iff verified on {len(samples)**2} ordered pairs")
    # expShift_injective: distinct transmonomials map to distinct images.
    imgs = [tuple(sorted(shift(m).items())) for m in samples]
    assert len(set(imgs)) == len(set(tuple(sorted(m.items())) for m in samples))
    print("expShift_injective confirmed on the test family")

"""Asymptotic comparison theorem: agreeToAllOrders(a,b) <=> a == b."""
from __future__ import annotations
from typing import Dict, List, Tuple

TransMono = Dict[int, float]
Key = Tuple[Tuple[int, float], ...]
TSeries = Dict[Key, float]

def mono(h: int, a: float) -> TransMono:
    return {} if a == 0.0 else {h: a}

def key(m: TransMono) -> Key:
    return tuple(sorted((h, a) for h, a in m.items() if a != 0.0))

def tseries(terms: List[Tuple[TransMono, float]]) -> TSeries:
    out: TSeries = {}
    for m, c in terms:
        out[key(m)] = out.get(key(m), 0.0) + c
    return {k: c for k, c in out.items() if c != 0.0}

def agree_to_all_orders(a: TSeries, b: TSeries) -> bool:
    diff: TSeries = dict(a)
    for k, c in b.items():
        diff[k] = diff.get(k, 0.0) - c
    return all(c == 0.0 for c in diff.values())

if __name__ == "__main__":
    a = tseries([(mono(1, 1.0), 1.0), (mono(0, 2.0), 3.0), (mono(0, 0.0), -7.0)])  # e^x + 3x^2 - 7
    b = tseries([(mono(0, 2.0), 3.0), (mono(0, 0.0), -7.0), (mono(1, 1.0), 1.0)])  # reordered
    assert agree_to_all_orders(a, b) is True   # agree to all orders => equal
    c = tseries([(mono(1, 1.0), 1.0), (mono(0, 2.0), 3.0)])  # missing the constant -7
    assert agree_to_all_orders(a, c) is False  # genuine difference => not equal
    print("agreeToAllOrders_iff_eq confirmed: agreement <=> equality")

