function EXP_SHIFT(series):
    out <- empty map
    for (monomial, coeff) in series:
        shifted <- { (h+1) : a  for (h, a) in monomial }
        out[shifted] <- out.get(shifted, 0) + coeff
    return { k : c  in out  if c != 0 }

function AGREE_TO_ALL_ORDERS(a, b):
    diff <- copy(a)
    for (monomial, coeff) in b:
        diff[monomial] <- diff.get(monomial, 0) - coeff
    return  every coefficient in diff is 0
